/** [sql-partsInput.xml] PartsInputMapper.updateOfPdStock **/
UPDATE TB_ST_01
 -- 재고 차감 (출고등록/입고삭제)
	SET ST01_QTY = ST01_QTY - #{outQty}

 -- 재고 증가 (입고등록/출고삭제)
	SET ST01_QTY = ST01_QTY + #{outQty}

WHERE 1=1
AND ST01_COMPANY = #{company}
AND ST01_FACTORY = #{factory}
AND ST01_CODE = #{code}
AND ST01_STOK = #{stock}

	AND ST01_LOT = #{lot}
	AND ST01_LOT_SEQ = #{lotSeq}

/** [sql-partsInput.xml] PartsInputMapper.updateOfSmdStock **/
UPDATE TB_ST_02
 -- 재고 차감 (출고등록/입고삭제)
	SET ST02_IPQTY = ST02_IPQTY - #{outQty}

 -- 재고 증가 (입고등록/출고삭제)
	SET ST02_IPQTY = ST02_IPQTY + #{outQty}

WHERE 1=1
AND ST02_COMPANY = #{company}
AND ST02_FACTORY = #{factory}
AND ST02_CODE = #{code}
AND ST02_STOK = #{stock}
AND ST02_GBN = 'OC'

	AND ST02_LOT = #{lot}
	AND ST02_LOT_SEQ = #{lotSeq}

mapper.insert:
		/** [sql-partsInput.xml] PartsInputMapper.insertOfPartInputHistory **/


            SELECT COALESCE(MAX(HS01_SEQ)+1,1) AS HS01_SEQ
            FROM TB_HS_01
            WHERE HS01_COMPANY = #{company}
              AND HS01_FACTORY = #{factory}
              AND TO_CHAR(HS01_DAT, 'YYYY-MM-DD') = #{hs01Dat}


		INSERT INTO TB_HS_01
		(
			  HS01_COMPANY
			, HS01_FACTORY
			, HS01_NO
			, HS01_DAT
			, HS01_SEQ
			, HS01_CODE
			, HS01_QTY
			, HS01_QR
			, HS01_INDTE
			, HS01_EMPNO
		)
		VALUES 
		(
			  #{company}
			, #{factory}
			, CONCAT(REPLACE(#{hs01Dat},'-',''), LPAD(#{hs01Dat},5,'0'))
			, #{hs01Dat}
			, #{hs01Seq}
			, #{code}
			, #{outQty}
			, #{st02Qrcode}
			, #{st03Empno}
			, SYSDATE
		)
